import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, delayRender, continueRender } from '../remotionShim';
// Module-level font loading for custom brand fonts
if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const format = url.endsWith(".otf") ? "opentype" : url.endsWith(".woff2") ? "woff2" : url.endsWith(".woff") ? "woff" : "truetype";
    const font = new FontFace(family, `url('${url}') format('${format}')`);
    font.load()
      .then(() => { 
        document.fonts.add(font); 
        continueRender(handle); 
      })
      .catch((err) => { 
        console.log(`Error loading ${family}`, err); 
        continueRender(handle); 
      });
  };
  
  loadCustomFont("mont-heavy", "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/9cf94644943949c08d64630e3ad272e4.ttf");
}



export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "CLEANER CONTROLS",
  titleFontFamily = "mont-heavy",
  neonColor = "#1ba9fa",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Canvas scale factor to keep everything responsive
  const s = Math.min(width, height) / 1080; 

  // Safely parse background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Geometry dimensions
  const R = 380 * s;   // Distance from center to small node centers
  const r0 = 150 * s;  // Radius of the center hub
  const r1 = 100 * s;  // Radius of the small nodes

  // Pre-calculate node positions and timings based on symmetry
  const nodesData = Array.from({ length: 5 }).map((_, i) => {
    // Start angle at top (-90 degrees) and distribute evenly
    const angle = -Math.PI / 2 + (i * 2 * Math.PI) / 5;
    const dx = Math.cos(angle);
    const dy = Math.sin(angle);
    
    // Staggered sequence timing
    const lineStartFrame = 25 + i * 15;
    const lineEndFrame = lineStartFrame + 20;
    const nodeStartFrame = lineEndFrame;
    const nodeEndFrame = nodeStartFrame + 15;
    
    return { dx, dy, lineStartFrame, lineEndFrame, nodeStartFrame, nodeEndFrame };
  });

  // Center hub animation states
  const centerScale = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14, mass: 0.8 }
  });
  const centerOpacity = interpolate(frame, [10, 20], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const centerShadowBlur = 20 * s + 8 * s * Math.sin(frame / 15);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* 1. Subtle Grid Pattern */}
      <svg width={width} height={height} style={{ position: "absolute", opacity: 0.1, transition: "none" }}>
        <defs>
          <pattern id="gridPattern" width={50 * s} height={50 * s} patternUnits="userSpaceOnUse">
            <path d={`M ${50 * s} 0 L 0 0 0 ${50 * s}`} fill="none" stroke="#ffffff" strokeWidth={Math.max(1, 1 * s)} style={{ transition: "none" }} />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#gridPattern)" />
      </svg>
      
      {/* 2. Radial Vignette Overlay to darken the edges */}
      <div style={{
        position: "absolute",
        width: "100%",
        height: "100%",
        background: `radial-gradient(circle at center, transparent 30%, ${bgColor} 100%)`,
        pointerEvents: "none",
        transition: "none"
      }} />

      {/* 3. Connecting Neon Lines & Rider Dots (SVG layer) */}
      <svg width={width} height={height} style={{ position: "absolute", overflow: "visible", transition: "none" }}>
        {nodesData.map((n, i) => {
          // Truncate path based on progress (De Casteljau's algorithm / Lerp for straight line)
          const t = interpolate(frame, [n.lineStartFrame, n.lineEndFrame], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
          const isLineVisible = t > 0;
          
          const currentX = (n.dx * r0) + (n.dx * (R - r1) - n.dx * r0) * t; 
          const currentY = (n.dy * r0) + (n.dy * (R - r1) - n.dy * r0) * t; 
          
          // Subtle idle oscillation applied to opacity of elements
          const linePulse = 0.6 + 0.4 * Math.sin((frame - n.lineStartFrame) / 10);

          return (
            <g key={`lines-${i}`}>
              {/* Blurred Glow Behind Line */}
              <line 
                x1={width / 2 + n.dx * r0} 
                y1={height / 2 + n.dy * r0} 
                x2={width / 2 + currentX} 
                y2={height / 2 + currentY} 
                stroke={neonColor} 
                strokeWidth={5 * s} 
                opacity={isLineVisible ? linePulse * 0.6 : 0} 
                filter={`blur(${3 * s}px)`} 
                style={{ transition: "none" }} 
              />
              {/* Core Sharp Line */}
              <line 
                x1={width / 2 + n.dx * r0} 
                y1={height / 2 + n.dy * r0} 
                x2={width / 2 + currentX} 
                y2={height / 2 + currentY} 
                stroke="#ffffff" 
                strokeWidth={1.5 * s} 
                opacity={isLineVisible ? linePulse : 0} 
                style={{ transition: "none" }} 
              />
              
              {/* Riding Glowing Dot at Tip */}
              <circle 
                cx={width / 2 + currentX} 
                cy={height / 2 + currentY} 
                r={2.5 * s} 
                fill="#ffffff" 
                opacity={isLineVisible ? linePulse : 0} 
              />
              <circle 
                cx={width / 2 + currentX} 
                cy={height / 2 + currentY} 
                r={7 * s} 
                fill={neonColor} 
                filter={`blur(${2 * s}px)`} 
                opacity={isLineVisible ? linePulse : 0} 
              />
            </g>
          );
        })}
      </svg>

      {/* 4. Peripheral Blurred Nodes (HTML layer for advanced box-shadow & filter) */}
      {nodesData.map((n, i) => {
        const nodeOpacity = interpolate(frame, [n.nodeStartFrame, n.nodeEndFrame], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        const shadowPulse = 10 * s + 5 * s * Math.sin((frame - n.nodeStartFrame) / 10);

        return (
          <div key={`node-${i}`} style={{
            position: "absolute",
            left: width / 2 + n.dx * R - r1,
            top: height / 2 + n.dy * R - r1,
            width: r1 * 2,
            height: r1 * 2,
            borderRadius: "50%",
            border: `${2 * s}px solid ${neonColor}`,
            boxShadow: `0 0 ${shadowPulse}px ${neonColor}, inset 0 0 ${shadowPulse}px ${neonColor}`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            filter: `blur(${3.5 * s}px)`,
            opacity: nodeOpacity,
            transition: "none",
            backgroundColor: "rgba(0,0,0,0.6)"
          }}>
            {/* Abstract/illegible ui shapes simulating faint inner content */}
            <div style={{ width: r1 * 0.45, height: r1 * 0.45, borderRadius: "50%", backgroundColor: "rgba(255,255,255,0.6)", marginBottom: r1 * 0.15 }} />
            <div style={{ width: r1 * 0.7, height: r1 * 0.15, backgroundColor: "rgba(255,255,255,0.6)", borderRadius: r1 * 0.05 }} />
          </div>
        );
      })}

      {/* 5. Center Hub */}
      <div style={{
        position: "absolute",
        left: width / 2 - r0,
        top: height / 2 - r0,
        width: r0 * 2,
        height: r0 * 2,
        borderRadius: "50%",
        border: `${3 * s}px solid ${neonColor}`,
        boxShadow: `0 0 ${centerShadowBlur}px ${neonColor}, inset 0 0 ${centerShadowBlur}px ${neonColor}`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        textAlign: "center",
        opacity: centerOpacity,
        transform: `scale(${centerScale})`,
        backgroundColor: "rgba(0,0,0,0.8)",
        transition: "none",
        zIndex: 10
      }}>
        <div style={{
          fontFamily: titleFontFamily,
          fontSize: 42 * s,
          color: "white",
          textTransform: "uppercase",
          lineHeight: 1.1,
          textShadow: `0 0 ${8 * s}px rgba(255,255,255,0.4)`,
          whiteSpace: "pre-wrap",
          width: "90%"
        }}>
          {title}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;